// Turn the recurrence report into a message a person will act on.
//
// LEAD WITH THE OUTCOME, not the job (notification-taxonomy rule 1). "2 patterns
// need a harness fix" is a title; "Recurrence review ran" makes the reader open
// the body to find out whether anything happened, every week, forever.
//
// THREE THINGS CAN BE WRONG, and they are NOT the same alarm:
//   1. harness debt — something failed twice and nobody decided anything.
//   2. a disposition is expiring — a dated promise to look again, coming due.
//      Said BEFORE it turns into a red gate: a prompt, not an ambush.
//   3. the data is stale — nobody has run `collect`, so the CI half of the
//      register is blind. This is the one that hides: no CI failures and no
//      collection produce the identical empty list, and only one of them is good
//      news. It is a WARN, never a quiet all-clear.
const d = $input.first().json || {};
const NL = String.fromCharCode(10);
const src = 'recurrence-review';

if (!Array.isArray(d.rows)) {
  return [{ json: { severity: 'warn', source: src,
    title: 'Recurrence lane: the lane call itself failed',
    message: ['The response had no shape we recognise — the register was not read.',
              JSON.stringify(d).slice(0, 400)].join(NL) } }];
}

const debt = d.harnessDebt || [];
const due = d.dispositionsDue || [];
const expired = due.filter(x => x.expired);
const errs = d.registerErrors || [];

// A source nobody has collected from is blind, not quiet.
const blind = Object.entries(d.sources || {})
  .filter(([, note]) => /collect` run|STALE|unavailable|not set/i.test(String(note)))
  .map(([name, note]) => name + ': ' + note);

const severity = (debt.length + expired.length + errs.length + blind.length) > 0
  ? 'warn' : 'info';

let title;
if (debt.length) {
  title = debt.length + ' pattern(s) failed twice with no harness fix — ' +
          String(debt[0].signature).slice(0, 60);
} else if (expired.length) {
  title = expired.length + ' recurrence disposition(s) EXPIRED — re-decide them';
} else if (errs.length) {
  title = 'The recurrence register could not be read';
} else if (blind.length) {
  title = 'Recurrence: nothing recurring, but ' + blind.length + ' source(s) blind';
} else if (due.length) {
  title = due.length + ' recurrence disposition(s) come due within 14 days';
} else {
  title = 'Recurrence: nothing new failed twice';
}

const lines = [];
if (debt.length) {
  lines.push('NEEDS A HARNESS FIX — seen >= ' + d.threshold + 'x, undispositioned:');
  debt.forEach(r => lines.push('  ' + r.count + 'x  ' + r.signature + NL +
    '        first ' + String(r.first).slice(0, 10) + ', last ' +
    String(r.last).slice(0, 10) + ', via ' + (r.sources || []).join('+')));
  lines.push('  -> fix the harness, or file it in reliability/recurrence.yaml');
  lines.push('');
}
if (due.length) {
  lines.push('DISPOSITIONS COMING DUE (a dated promise to look again):');
  due.forEach(x => lines.push('  ' + (x.expired ? 'EXPIRED ' : 'due ') + x.until +
    '  [' + x.status + '] ' + (x.title || x.match) +
    (x.next_action ? NL + '        next: ' + String(x.next_action).slice(0, 200) : '')));
  lines.push('');
}
if (errs.length) {
  lines.push('REGISTER ERRORS:');
  errs.forEach(e => lines.push('  ' + e));
  lines.push('');
}

// Coverage before totals — the same rule the digest follows. A count means
// nothing until you know what it was counted over.
lines.push('Sources (' + d.windowDays + 'd window):');
Object.entries(d.sources || {}).forEach(([k, v]) => lines.push('  ' + k + ': ' + v));
if (blind.length) {
  lines.push('  NOTE: a blind source reports zero, which is indistinguishable from a');
  lines.push('        quiet week. Run `python scripts/recurrence.py collect` on the host.');
}
lines.push('');
lines.push('Everything counted (' + d.registerEntries + ' register entry(ies)):');
(d.rows || []).forEach(r => lines.push('  ' + String(r.count).padStart(3) + 'x  ' +
  String(r.status || '').padEnd(16) + ' ' + String(r.signature).slice(0, 70)));
if (!d.rows.length) {
  lines.push('  (nothing at all — see the source notes above)');
}

return [{ json: { severity, source: src, title, message: lines.join(NL) } }];
